from __future__ import annotations

from typing import Optional


def _strip_quotes(value: str) -> str:
    value = value.strip()
    if len(value) >= 2 and value[0] == value[-1] and value[0] in ("'", '"'):
        return value[1:-1].strip()
    return value


def _parse_content_type(content_type: str) -> tuple[str, Optional[str]]:
    """
    Parse a Content-Type header value into (mime, charset).

    - Returns mime lower-cased, without parameters.
    - Returns charset lower-cased or None.
    - Parameter values may be quoted.
    """
    if not isinstance(content_type, str):
        raise TypeError("content_type must be a str")

    parts = [p.strip() for p in content_type.split(";")]
    mime = parts[0].strip().lower()

    charset: Optional[str] = None
    for param in parts[1:]:
        if not param:
            continue
        if "=" not in param:
            continue
        key, val = param.split("=", 1)
        key = key.strip().lower()
        val = _strip_quotes(val)
        if key == "charset":
            charset = val.lower() if val else None

    return mime, charset


def _detect_image_from_signature(data: bytes) -> Optional[str]:
    """
    Detect common image formats from the first bytes signature.

    Returns one of: "png", "jpeg", "gif" or None.
    """
    if not data:
        return None

    # PNG: 89 50 4E 47 0D 0A 1A 0A
    if data.startswith(b"\x89PNG\r\n\x1a\n"):
        return "png"

    # JPEG: FF D8 FF (also allow common variants where third byte can vary)
    if len(data) >= 3 and data[0:3] == b"\xFF\xD8\xFF":
        return "jpeg"

    # GIF: ASCII "GIF87a" or "GIF89a"
    if data.startswith(b"GIF87a") or data.startswith(b"GIF89a"):
        return "gif"

    return None


def describe_upload(content_type: str, data: bytes) -> dict:
    """
    Given the request's Content-Type header value and the first bytes of the body,
    return a dict of:
      {
        "mime": <lower-cased media type without parameters>,
        "charset": <lower-cased charset parameter or None>,
        "image": <"png"|"jpeg"|"gif"|None, detected from the data's signature bytes>
      }
    """
    mime, charset = _parse_content_type(content_type)
    image = _detect_image_from_signature(data)
    return {"mime": mime, "charset": charset, "image": image}
